-- Pendientes de Luciano et al. (2009), 2026-11-25 (aprobado por el usuario).
begin;
update programas_base set actividad_tablet = $j${"tipo": "distincion", "niveles": [{"modo": "igual_diferente", "nombre": "Igual y diferente", "opciones": 2}, {"modo": "dimension", "nombre": "Igual o diferente: color", "dimension": "color", "opciones": 2}, {"modo": "dimension", "nombre": "Igual o diferente: forma", "dimension": "forma", "opciones": 2}, {"modo": "dimension", "nombre": "Igual o diferente: tamaño", "dimension": "tamano", "opciones": 2}, {"modo": "dimension", "nombre": "Igual o diferente: mezclado", "dimension": "mezcla", "opciones": 2}, {"modo": "intruso", "nombre": "Cuál es diferente", "opciones": 4}, {"modo": "sutil", "nombre": "Diferencias sutiles", "opciones": 2}]}$j$::jsonb, instrucciones_terapeuta = instrucciones_terapeuta || $j$

Igual o diferente en una dimensión (niveles 2 a 5; Luciano et al., 2009): dos figuras y la pregunta por una sola propiedad («¿Son del mismo color o de color diferente?»). Primero un bloque por dimensión (color, forma, tamaño) y después mezcladas. Las otras propiedades juegan en contra: si son del mismo color, casi siempre difieren en forma o tamaño, y si son de color diferente, casi siempre coinciden en lo demás; así no basta con mirar si «se parecen».$j$, contenido_actualizado_at = now() where clinica_id is null and nombre = 'Abstraer Claves de Distinción' and position('una dimensión (niveles 2 a 5' in instrucciones_terapeuta) = 0;
update programas_base set instrucciones_terapeuta = instrucciones_terapeuta || $j$

Ampliar la clave (Luciano et al., 2009): una vez dominado el programa, en las sondas de generalización use otras palabras para la misma relación («¿Qué es lo mismo que esto?», «¿Qué va con esto?», «Busca otro igual»), para que la respuesta no quede ligada a una sola frase.$j$, contenido_actualizado_at = now() where clinica_id is null and activo and dominio_id = (select id from dominios_curriculo where codigo = '2.1') and position('Ampliar la clave (Luciano' in instrucciones_terapeuta) = 0;
insert into requisitos_programa (programa_base_id, requisito_id) select (select id from programas_base where clinica_id is null and nombre = 'Abstraer Claves de Oposición'), (select id from programas_base where clinica_id is null and nombre = 'Vincular Mutuamente Características con sus Nombres') where not exists (select 1 from requisitos_programa where programa_base_id = (select id from programas_base where clinica_id is null and nombre = 'Abstraer Claves de Oposición') and requisito_id = (select id from programas_base where clinica_id is null and nombre = 'Vincular Mutuamente Características con sus Nombres'));
insert into requisitos_programa (programa_base_id, requisito_id) select (select id from programas_base where clinica_id is null and nombre = 'Abstraer Claves de Oposición'), (select id from programas_base where clinica_id is null and nombre = 'Responder Sí o No') where not exists (select 1 from requisitos_programa where programa_base_id = (select id from programas_base where clinica_id is null and nombre = 'Abstraer Claves de Oposición') and requisito_id = (select id from programas_base where clinica_id is null and nombre = 'Responder Sí o No'));
update programas_base set instrucciones_terapeuta = regexp_replace(instrucciones_terapeuta, E'(Requisito previo:[^\n]*)', E'\\1 Además, nombra y reconoce los dos polos que se van a usar (abierto y cerrado, lleno y vacío…; ver "Vincular Mutuamente Características con sus Nombres" del dominio 2.2) y responde sí o no (ver "Responder Sí o No" del dominio 1.4), que es la primera oposición que aprende (Luciano et al., 2009).'), contenido_actualizado_at = now() where clinica_id is null and nombre = 'Abstraer Claves de Oposición' and position('Responder Sí o No' in instrucciones_terapeuta) = 0;
update programas_base set objetivo = replace(objetivo, 'y generaliza esa respuesta a dimensiones no entrenadas.', 'y generaliza esa respuesta a objetos nuevos (sondas con categorías que no salen en el entrenamiento).'), contenido_actualizado_at = now() where clinica_id is null and nombre = 'Abstraer Claves de Comparación';
update programas_base set instrucciones_terapeuta = instrucciones_terapeuta || $j$

Si falla un test (Luciano et al., 2009): vuelva un momento a lo no arbitrario con la misma dimensión, con dos objetos reales que se vean distintos («Este es más alto que este»; ver "Abstraer Claves de Comparación"), y retome las frases en cuanto responda bien. Las fichas iguales son el paso intermedio entre los objetos y las frases.$j$, contenido_actualizado_at = now() where clinica_id is null and nombre = 'Vincular Mutuamente Relaciones de Comparación' and position('Si falla un test (Luciano' in instrucciones_terapeuta) = 0;
update programas_base set instrucciones_terapeuta = instrucciones_terapeuta || $j$

Si falla un test (Luciano et al., 2009): vuelva un momento a lo no arbitrario con la misma dimensión, con dos objetos reales que se vean distintos («Este es más alto que este»; ver "Abstraer Claves de Comparación"), y retome las frases en cuanto responda bien. Las fichas iguales son el paso intermedio entre los objetos y las frases.$j$, contenido_actualizado_at = now() where clinica_id is null and nombre = 'Derivar Relaciones de Comparación en Redes Combinatorias' and position('Si falla un test (Luciano' in instrucciones_terapeuta) = 0;
with nueva as (
  insert into clases_rft_base (programa_base_id, nombre, grupo, orden, consignas, respuestas_esperadas, opciones_por_fase)
  values ((select id from programas_base where clinica_id is null and nombre = 'Derivar Relaciones de Comparación en Redes Combinatorias'), 'Clase 28', 'Grupo 10', 28, $j${"entrenamiento:B→A": "Tavi es más alto que Kemo. ¿Quién es más alto?", "test_mutuo:A→B": "Tavi es más alto que Kemo. ¿Quién es más bajo?", "entrenamiento:C→B": "Kemo es más alto que Lusa. ¿Quién es más alto?", "test_mutuo:B→C": "Kemo es más alto que Lusa. ¿Quién es más bajo?", "entrenamiento:D→C": "Lusa es más alto que Bifo. ¿Quién es más alto?", "test_mutuo:C→D": "Lusa es más alto que Bifo. ¿Quién es más bajo?", "test_combinatorio:C→A": "Tavi es más alto que Kemo. Kemo es más alto que Lusa. Lusa es más alto que Bifo. ¿Quién es más alto, Tavi o Lusa?", "test_combinatorio:A→C": "Tavi es más alto que Kemo. Kemo es más alto que Lusa. Lusa es más alto que Bifo. ¿Quién es más bajo, Lusa o Tavi?", "transformacion_funciones:C→A": "Tavi es más alto que Kemo. Kemo es más alto que Lusa. Lusa es más alto que Bifo. Hay que coger un bote de la estantería más alta. Solo pueden ir Lusa o Tavi. ¿A quién sería mejor pedírselo?", "transformacion_funciones:A→C": "Tavi es más alto que Kemo. Kemo es más alto que Lusa. Lusa es más alto que Bifo. Hay que pasar por debajo de una rama muy baja. Solo pueden ir Tavi o Lusa. ¿Quién pasaría mejor?", "test_combinatorio:D→A": "Tavi es más alto que Kemo. Kemo es más alto que Lusa. Lusa es más alto que Bifo. ¿Quién es más alto, Tavi o Bifo?", "test_combinatorio:A→D": "Tavi es más alto que Kemo. Kemo es más alto que Lusa. Lusa es más alto que Bifo. ¿Quién es más bajo, Bifo o Tavi?", "transformacion_funciones:D→A": "Tavi es más alto que Kemo. Kemo es más alto que Lusa. Lusa es más alto que Bifo. Hay que coger un bote de la estantería más alta. Solo pueden ir Bifo o Tavi. ¿A quién sería mejor pedírselo?", "transformacion_funciones:A→D": "Tavi es más alto que Kemo. Kemo es más alto que Lusa. Lusa es más alto que Bifo. Hay que pasar por debajo de una rama muy baja. Solo pueden ir Tavi o Bifo. ¿Quién pasaría mejor?"}$j$::jsonb, $j${"entrenamiento:B→A": "Tavi", "test_mutuo:A→B": "Kemo", "entrenamiento:C→B": "Kemo", "test_mutuo:B→C": "Lusa", "entrenamiento:D→C": "Lusa", "test_mutuo:C→D": "Bifo", "test_combinatorio:C→A": "Tavi", "test_combinatorio:A→C": "Lusa", "transformacion_funciones:C→A": "Tavi", "transformacion_funciones:A→C": "Lusa", "test_combinatorio:D→A": "Tavi", "test_combinatorio:A→D": "Bifo", "transformacion_funciones:D→A": "Tavi", "transformacion_funciones:A→D": "Bifo"}$j$::jsonb, '{}'::jsonb) returning id)
insert into estimulos_rft_base (clase_base_id, etiqueta, posicion, nombre, concepto_imagen)
select id, 'A28', 'A', $j$Tavi$j$, null from nueva union all select id, 'B28', 'B', $j$Kemo$j$, null from nueva union all select id, 'C28', 'C', $j$Lusa$j$, null from nueva union all select id, 'D28', 'D', $j$Bifo$j$, null from nueva;
with nueva as (
  insert into clases_rft_base (programa_base_id, nombre, grupo, orden, consignas, respuestas_esperadas, opciones_por_fase)
  values ((select id from programas_base where clinica_id is null and nombre = 'Derivar Relaciones de Comparación en Redes Combinatorias'), 'Clase 29', 'Grupo 10', 29, $j${"entrenamiento:B→A": "Pesu es más lento que Rano. ¿Quién es más rápido?", "test_mutuo:A→B": "Pesu es más lento que Rano. ¿Quién es más lento?", "entrenamiento:C→B": "Golk es más lento que Pesu. ¿Quién es más rápido?", "test_mutuo:B→C": "Golk es más lento que Pesu. ¿Quién es más lento?", "entrenamiento:D→C": "Nimo es más lento que Golk. ¿Quién es más rápido?", "test_mutuo:C→D": "Nimo es más lento que Golk. ¿Quién es más lento?", "test_combinatorio:C→A": "Nimo es más lento que Golk. Golk es más lento que Pesu. Pesu es más lento que Rano. ¿Quién es más rápido, Rano o Golk?", "test_combinatorio:A→C": "Nimo es más lento que Golk. Golk es más lento que Pesu. Pesu es más lento que Rano. ¿Quién es más lento, Golk o Rano?", "transformacion_funciones:C→A": "Nimo es más lento que Golk. Golk es más lento que Pesu. Pesu es más lento que Rano. Hay que llegar el primero a la meta. Solo pueden ir Golk o Rano. ¿A quién elegirías para la carrera?", "transformacion_funciones:A→C": "Nimo es más lento que Golk. Golk es más lento que Pesu. Pesu es más lento que Rano. Hay que llevar un vaso muy lleno hasta la mesa sin derramarlo. Solo pueden ir Rano o Golk. ¿A quién se lo darías, para que vaya con calma?", "test_combinatorio:D→A": "Nimo es más lento que Golk. Golk es más lento que Pesu. Pesu es más lento que Rano. ¿Quién es más rápido, Rano o Nimo?", "test_combinatorio:A→D": "Nimo es más lento que Golk. Golk es más lento que Pesu. Pesu es más lento que Rano. ¿Quién es más lento, Nimo o Rano?", "transformacion_funciones:D→A": "Nimo es más lento que Golk. Golk es más lento que Pesu. Pesu es más lento que Rano. Hay que llegar el primero a la meta. Solo pueden ir Nimo o Rano. ¿A quién elegirías para la carrera?", "transformacion_funciones:A→D": "Nimo es más lento que Golk. Golk es más lento que Pesu. Pesu es más lento que Rano. Hay que llevar un vaso muy lleno hasta la mesa sin derramarlo. Solo pueden ir Rano o Nimo. ¿A quién se lo darías, para que vaya con calma?"}$j$::jsonb, $j${"entrenamiento:B→A": "Rano", "test_mutuo:A→B": "Pesu", "entrenamiento:C→B": "Pesu", "test_mutuo:B→C": "Golk", "entrenamiento:D→C": "Golk", "test_mutuo:C→D": "Nimo", "test_combinatorio:C→A": "Rano", "test_combinatorio:A→C": "Golk", "transformacion_funciones:C→A": "Rano", "transformacion_funciones:A→C": "Golk", "test_combinatorio:D→A": "Rano", "test_combinatorio:A→D": "Nimo", "transformacion_funciones:D→A": "Rano", "transformacion_funciones:A→D": "Nimo"}$j$::jsonb, '{}'::jsonb) returning id)
