  values ((select id from programas_base where clinica_id is null and nombre = 'Derivar Relaciones de Comparación en Redes Combinatorias'), 'Clase 30', 'Grupo 10', 30, $j${"entrenamiento:B→A": "Daf es más pesado que Suko. ¿Quién es más pesado?", "test_mutuo:A→B": "Daf es más pesado que Suko. ¿Quién es más ligero?", "entrenamiento:C→B": "Suko es más pesado que Mavi. ¿Quién es más pesado?", "test_mutuo:B→C": "Suko es más pesado que Mavi. ¿Quién es más ligero?", "entrenamiento:D→C": "Mavi es más pesado que Tepo. ¿Quién es más pesado?", "test_mutuo:C→D": "Mavi es más pesado que Tepo. ¿Quién es más ligero?", "test_combinatorio:C→A": "Mavi es más pesado que Tepo. Suko es más pesado que Mavi. Daf es más pesado que Suko. ¿Quién es más pesado, Daf o Mavi?", "test_combinatorio:A→C": "Mavi es más pesado que Tepo. Suko es más pesado que Mavi. Daf es más pesado que Suko. ¿Quién es más ligero, Mavi o Daf?", "transformacion_funciones:C→A": "Mavi es más pesado que Tepo. Suko es más pesado que Mavi. Daf es más pesado que Suko. Hay que sujetar la cuerda para que el globo no se vuele. Solo pueden ir Mavi o Daf. ¿Quién la sujetaría mejor?", "transformacion_funciones:A→C": "Mavi es más pesado que Tepo. Suko es más pesado que Mavi. Daf es más pesado que Suko. Hay que subir a una rama muy fina sin que se rompa. Solo pueden ir Daf o Mavi. ¿Quién debería subir?", "test_combinatorio:D→A": "Mavi es más pesado que Tepo. Suko es más pesado que Mavi. Daf es más pesado que Suko. ¿Quién es más pesado, Daf o Tepo?", "test_combinatorio:A→D": "Mavi es más pesado que Tepo. Suko es más pesado que Mavi. Daf es más pesado que Suko. ¿Quién es más ligero, Tepo o Daf?", "transformacion_funciones:D→A": "Mavi es más pesado que Tepo. Suko es más pesado que Mavi. Daf es más pesado que Suko. Hay que sujetar la cuerda para que el globo no se vuele. Solo pueden ir Tepo o Daf. ¿Quién la sujetaría mejor?", "transformacion_funciones:A→D": "Mavi es más pesado que Tepo. Suko es más pesado que Mavi. Daf es más pesado que Suko. Hay que subir a una rama muy fina sin que se rompa. Solo pueden ir Daf o Tepo. ¿Quién debería subir?"}$j$::jsonb, $j${"entrenamiento:B→A": "Daf", "test_mutuo:A→B": "Suko", "entrenamiento:C→B": "Suko", "test_mutuo:B→C": "Mavi", "entrenamiento:D→C": "Mavi", "test_mutuo:C→D": "Tepo", "test_combinatorio:C→A": "Daf", "test_combinatorio:A→C": "Mavi", "transformacion_funciones:C→A": "Daf", "transformacion_funciones:A→C": "Mavi", "test_combinatorio:D→A": "Daf", "test_combinatorio:A→D": "Tepo", "transformacion_funciones:D→A": "Daf", "transformacion_funciones:A→D": "Tepo"}$j$::jsonb, '{}'::jsonb) returning id)
