select id, 'A30', 'A', $j$Daf$j$, null from nueva union all select id, 'B30', 'B', $j$Suko$j$, null from nueva union all select id, 'C30', 'C', $j$Mavi$j$, null from nueva union all select id, 'D30', 'D', $j$Tepo$j$, null from nueva;
with nueva as (
  insert into clases_rft_base (programa_base_id, nombre, grupo, orden, consignas, respuestas_esperadas, opciones_por_fase)
  values ((select id from programas_base where clinica_id is null and nombre = 'Derivar Relaciones de Comparación en Redes Combinatorias'), 'Clase 31', 'Grupo 11', 31, $j${"entrenamiento:B→A": "Rimo es más bajo que Kalu. ¿Quién es más alto?", "test_mutuo:A→B": "Rimo es más bajo que Kalu. ¿Quién es más bajo?", "entrenamiento:C→B": "Bosa es más bajo que Rimo. ¿Quién es más alto?", "test_mutuo:B→C": "Bosa es más bajo que Rimo. ¿Quién es más bajo?", "entrenamiento:D→C": "Fena es más bajo que Bosa. ¿Quién es más alto?", "test_mutuo:C→D": "Fena es más bajo que Bosa. ¿Quién es más bajo?", "entrenamiento:E→D": "Gutu es más bajo que Fena. ¿Quién es más alto?", "test_mutuo:D→E": "Gutu es más bajo que Fena. ¿Quién es más bajo?", "test_combinatorio:C→A": "Rimo es más bajo que Kalu. Bosa es más bajo que Rimo. Fena es más bajo que Bosa. Gutu es más bajo que Fena. ¿Quién es más alto, Kalu o Bosa?", "test_combinatorio:A→C": "Rimo es más bajo que Kalu. Bosa es más bajo que Rimo. Fena es más bajo que Bosa. Gutu es más bajo que Fena. ¿Quién es más bajo, Bosa o Kalu?", "transformacion_funciones:C→A": "Rimo es más bajo que Kalu. Bosa es más bajo que Rimo. Fena es más bajo que Bosa. Gutu es más bajo que Fena. Hay que coger un bote de la estantería más alta. Solo pueden ir Bosa o Kalu. ¿A quién sería mejor pedírselo?", "transformacion_funciones:A→C": "Rimo es más bajo que Kalu. Bosa es más bajo que Rimo. Fena es más bajo que Bosa. Gutu es más bajo que Fena. Hay que pasar por debajo de una rama muy baja. Solo pueden ir Kalu o Bosa. ¿Quién pasaría mejor?", "test_combinatorio:D→A": "Rimo es más bajo que Kalu. Bosa es más bajo que Rimo. Fena es más bajo que Bosa. Gutu es más bajo que Fena. ¿Quién es más alto, Kalu o Fena?", "test_combinatorio:A→D": "Rimo es más bajo que Kalu. Bosa es más bajo que Rimo. Fena es más bajo que Bosa. Gutu es más bajo que Fena. ¿Quién es más bajo, Fena o Kalu?", "transformacion_funciones:D→A": "Rimo es más bajo que Kalu. Bosa es más bajo que Rimo. Fena es más bajo que Bosa. Gutu es más bajo que Fena. Hay que coger un bote de la estantería más alta. Solo pueden ir Fena o Kalu. ¿A quién sería mejor pedírselo?", "transformacion_funciones:A→D": "Rimo es más bajo que Kalu. Bosa es más bajo que Rimo. Fena es más bajo que Bosa. Gutu es más bajo que Fena. Hay que pasar por debajo de una rama muy baja. Solo pueden ir Kalu o Fena. ¿Quién pasaría mejor?", "test_combinatorio:E→A": "Rimo es más bajo que Kalu. Bosa es más bajo que Rimo. Fena es más bajo que Bosa. Gutu es más bajo que Fena. ¿Quién es más alto, Kalu o Gutu?", "test_combinatorio:A→E": "Rimo es más bajo que Kalu. Bosa es más bajo que Rimo. Fena es más bajo que Bosa. Gutu es más bajo que Fena. ¿Quién es más bajo, Gutu o Kalu?", "transformacion_funciones:E→A": "Rimo es más bajo que Kalu. Bosa es más bajo que Rimo. Fena es más bajo que Bosa. Gutu es más bajo que Fena. Hay que coger un bote de la estantería más alta. Solo pueden ir Gutu o Kalu. ¿A quién sería mejor pedírselo?", "transformacion_funciones:A→E": "Rimo es más bajo que Kalu. Bosa es más bajo que Rimo. Fena es más bajo que Bosa. Gutu es más bajo que Fena. Hay que pasar por debajo de una rama muy baja. Solo pueden ir Kalu o Gutu. ¿Quién pasaría mejor?"}$j$::jsonb, $j${"entrenamiento:B→A": "Kalu", "test_mutuo:A→B": "Rimo", "entrenamiento:C→B": "Rimo", "test_mutuo:B→C": "Bosa", "entrenamiento:D→C": "Bosa", "test_mutuo:C→D": "Fena", "entrenamiento:E→D": "Fena", "test_mutuo:D→E": "Gutu", "test_combinatorio:C→A": "Kalu", "test_combinatorio:A→C": "Bosa", "transformacion_funciones:C→A": "Kalu", "transformacion_funciones:A→C": "Bosa", "test_combinatorio:D→A": "Kalu", "test_combinatorio:A→D": "Fena", "transformacion_funciones:D→A": "Kalu", "transformacion_funciones:A→D": "Fena", "test_combinatorio:E→A": "Kalu", "test_combinatorio:A→E": "Gutu", "transformacion_funciones:E→A": "Kalu", "transformacion_funciones:A→E": "Gutu"}$j$::jsonb, '{}'::jsonb) returning id)
insert into estimulos_rft_base (clase_base_id, etiqueta, posicion, nombre, concepto_imagen)
select id, 'A31', 'A', $j$Kalu$j$, null from nueva union all select id, 'B31', 'B', $j$Rimo$j$, null from nueva union all select id, 'C31', 'C', $j$Bosa$j$, null from nueva union all select id, 'D31', 'D', $j$Fena$j$, null from nueva union all select id, 'E31', 'E', $j$Gutu$j$, null from nueva;
